export function parseNumber(raw) {
 const s=String(raw).trim().replaceAll('−','-');
 if(!s) return null;
 const number='[+-]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)';
 if(new RegExp(`^${number}$`).test(s)){const n=Number(s);return Number.isFinite(n)?n:null;}
 const match=s.match(new RegExp(`^(${number})\\s*\\/\\s*(${number})$`));
 if(!match || Number(match[2])===0) return null;
 const n=Number(match[1])/Number(match[2]); return Number.isFinite(n)?n:null;
}
export function gradeAnswer(problem, raw){const n=parseNumber(raw); return n===null?'invalid':Math.abs(n-problem.answer)<=Math.max(0.0001,Math.abs(problem.answer)*0.0001)?'correct':'incorrect';}
